        let src2 = make_pattern_buf(4096, 0xAA);
        let flags1 = unsafe { tdefl_create_comp_flags_from_zip_params(6, 15, 0) } as i32;
        let flags2 = unsafe { tdefl_create_comp_flags_from_zip_params(1, -15, 0) } as i32;

        let mut out1 = vec![0u8; 8192];
