fn fold(acc: u64, x: u64) -> u64 {
    acc.rotate_left(7) ^ x.wrapping_mul(0x9E37_79B1_85EB_CA87)
}

fn bytes_checksum(data: &[u8]) -> u64 {
    let mut acc = 0u64;
    for (i, &b) in data.iter().enumerate() {
        acc = fold(acc, ((i as u64) << 8) ^ b as u64);
    }
    acc
}

fn cstr_len(p: *const c_char) -> u64 {
    if p.is_null() {
        0
    } else {
        unsafe { CStr::from_ptr(p).to_bytes().len() as u64 }
    }
}

fn write_file(path: &str, bytes: &[u8]) -> bool {
