}

fn make_text_payload(mult: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(mult * 256);
    for i in 0..mult {
        let level = match i % 5 {
            0 => "INFO",
            1 => "WARN",
            2 => "DEBUG",
            3 => "TRACE",
            _ => "ERROR",
        };
        let region = match i % 4 {
            0 => "us-east-1",
            1 => "eu-west-1",
            2 => "ap-south-1",
            _ => "local",
        };
        let line = format!(
            "{{\"ts\":\"2024-05-{day:02}T12:{min:02}:{sec:02}Z\",\"lvl\":\"{lvl}\",\"svc\":\"gateway\",\"region\":\"{region}\",\"req\":{req},\"user\":\"user_{user:05}\",\"path\":\"/api/v1/items/{item}\",\"status\":{status},\"latency_ms\":{lat},\"csv\":\"{a},{b},{c}\",\"msg\":\"deterministic repeated record block {blk}\"}}\n",
            day = (i % 28) + 1,
            min = i % 60,
            sec = (i * 7) % 60,
            lvl = level,
            region = region,
            req = 10_000u64 + i as u64,
            user = (i * 17) % 100_000,
            item = i % 4096,
            status = [200, 200, 200, 201, 404, 500][i % 6],
            lat = 3 + (i * 13) % 250,
            a = i,
            b = i.wrapping_mul(7),
            c = i ^ 0x55AA,
            blk = i % 128
        );
        out.extend_from_slice(line.as_bytes());
    }
    out
}

fn make_mixed_payload(mult: usize) -> Vec<u8> {
    let mut out = Vec::with_capacity(mult * 320);
    let header = b"MZRAW\x00HDR\x01\x02\x03\x04REPEAT-BLOCK:";
    for i in 0..mult {
        out.extend_from_slice(header);
        out.extend_from_slice(&(i as u32).to_le_bytes());
        out.extend_from_slice(&((i as u32).wrapping_mul(2654435761)).to_le_bytes());
        let text = format!(
            "section={},name=file_{:06}.bin,type=chunk,flags={:04x},note=structured-binary-looking-data\n",
            i,
            i,
            (i * 9) & 0xFFFF
        );
        out.extend_from_slice(text.as_bytes());
        for j in 0..48usize {
            let v = (((i as u32).wrapping_mul(31)).wrapping_add(j as u32 * 17) ^ 0xA5A55A5A)
                .to_le_bytes();
            out.extend_from_slice(&v);
        }
        out.extend_from_slice(b"\n--PAYLOAD-SPLIT--\n");
        out.extend_from_slice(
            b"HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nX-Repeat: yes\r\n\r\n",
        );
    }
    out
}

