fn compress_zlib_blob(data: &[u8], level: i32) -> Option<Vec<u8>> {
    unsafe {
        let bound = mz::mz_compressBound(data.len() as mz::mz_ulong) as usize;
        if bound == 0 {
            return Some(Vec::new());
        }
        let mut out = vec![0u8; bound];
        let mut out_len = bound as mz::mz_ulong;
        let rc = mz::mz_compress2(
            out.as_mut_ptr(),
            &mut out_len,
            if data.is_empty() { ptr::null() } else { data.as_ptr() },
            data.len() as mz::mz_ulong,
            level,
        );
        if rc >= 0 {
            out.truncate(out_len as usize);
            Some(out)
        } else {
            None
        }
    }
}

fn build_zip_blob(members: &[(&[u8], &'static [u8], Option<&'static [u8]>)]) -> Option<Vec<u8>> {
    unsafe {
        let mut za = MaybeUninit::<zip::mz_zip_archive>::zeroed();
        let pzip = za.as_mut_ptr();
        zip::mz_zip_zero_struct(pzip);

        let mut ok = zip::mz_zip_writer_init_heap(pzip, 0, 0) != 0;
        if !ok {
            let _ = zip::mz_zip_writer_end(pzip);
            return None;
        }

        for (idx, (data, name, comment)) in members.iter().enumerate() {
            let added = if idx % 2 == 0 {
                zip::mz_zip_writer_add_mem(
                    pzip,
                    name.as_ptr() as *const c_char,
                    if data.is_empty() {
                        ptr::null()
                    } else {
                        data.as_ptr() as *const c_void
                    },
                    data.len(),
                    6u32,
                )
            } else {
                let c = comment
                    .map(|x| x.as_ptr() as *const c_void)
                    .unwrap_or(ptr::null());
                let clen = comment.map(|x| x.len() as u16).unwrap_or(0);
                let crc = mz::mz_crc32(
                    0,
                    if data.is_empty() {
                        ptr::null()
                    } else {
                        data.as_ptr()
                    },
                    data.len(),
                ) as u32;
                zip::mz_zip_writer_add_mem_ex(
                    pzip,
                    name.as_ptr() as *const c_char,
                    if data.is_empty() {
                        ptr::null()
                    } else {
                        data.as_ptr() as *const c_void
                    },
                    data.len(),
                    c,
                    clen,
                    6u32,
                    data.len() as u64,
                    crc,
                )
            };
            ok &= added != 0;
        }

        let finalized = zip::mz_zip_writer_finalize_archive(pzip) != 0;
        ok &= finalized;

        let mut heap_ptr: *mut c_void = ptr::null_mut();
        let mut heap_size: usize = 0;
        let finalized_heap =
            zip::mz_zip_writer_finalize_heap_archive(pzip, &mut heap_ptr, &mut heap_size) != 0;
        ok &= finalized_heap;

        let out = if ok && !heap_ptr.is_null() {
            let bytes = slice::from_raw_parts(heap_ptr as *const u8, heap_size).to_vec();
            mz::mz_free(heap_ptr);
            Some(bytes)
        } else {
            if !heap_ptr.is_null() {
                mz::mz_free(heap_ptr);
            }
            None
        };

        let _ = zip::mz_zip_writer_end(pzip);
        out
    }
}

fn mz_stream_roundtrip(input: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_def_rc = 0i32;
    let mut last_inf_rc = 0i32;
    let mut last_err_strlen = 0u64;

    for _ in 0..iters {
        unsafe {
            let mut def = MaybeUninit::<mz::mz_stream>::zeroed().assume_init();
            let mut comp: Vec<u8> = Vec::new();
            let mut recovered: Vec<u8> = Vec::new();

            let init_rc = mz::mz_deflateInit(&mut def as *mut _, 6);
            last_def_rc = init_rc;
            digest = fold(digest, init_rc as u64);
            if init_rc == 0 {
                let _ = mz::mz_deflateReset(&mut def as *mut _);
                let bound =
                    mz::mz_deflateBound(&mut def as *mut _, input.len() as mz::mz_ulong) as usize;
                let cap = bound.max(128);
                comp.resize(cap, 0u8);

                let mut in_pos = 0usize;
                let mut out_pos = 0usize;

                loop {
                    if def.avail_in == 0 && in_pos < input.len() {
                        let chunk = (input.len() - in_pos).min(1024);
                        def.next_in = input[in_pos..].as_ptr();
                        def.avail_in = chunk as u32;
                        in_pos += chunk;
                    }
                    if def.avail_out == 0 {
                        if out_pos >= comp.len() {
                            comp.resize(comp.len().saturating_add(1024).max(1024), 0);
                        }
                        def.next_out = comp[out_pos..].as_mut_ptr();
                        def.avail_out = (comp.len() - out_pos) as u32;
                    }

                    let flush = if in_pos >= input.len() && def.avail_in == 0 {
                        4
                    } else {
                        0
                    };
                    let rc = mz::mz_deflate(&mut def as *mut _, flush);
                    last_def_rc = rc;
                    digest = fold(digest, rc as u64);
                    out_pos = def.total_out as usize;
                    if rc == 1 || rc < 0 {
                        break;
                    }
                    if flush == 4 && def.avail_out != 0 && rc == 0 && def.avail_in == 0 {
                        break;
                    }
                }

                comp.truncate(def.total_out as usize);
                let _ = mz::mz_deflateEnd(&mut def as *mut _);
            }

            let mut inf = MaybeUninit::<mz::mz_stream>::zeroed().assume_init();
            let inf_init = mz::mz_inflateInit(&mut inf as *mut _);
            last_inf_rc = inf_init;
            digest = fold(digest, inf_init as u64);
            if inf_init == 0 {
                let _ = mz::mz_inflateReset(&mut inf as *mut _);
                recovered.resize(input.len().saturating_add(1024).max(128), 0u8);

                let mut in_pos = 0usize;
                let mut out_pos = 0usize;

                loop {
                    if inf.avail_in == 0 && in_pos < comp.len() {
                        let chunk = (comp.len() - in_pos).min(777);
                        inf.next_in = comp[in_pos..].as_ptr();
                        inf.avail_in = chunk as u32;
                        in_pos += chunk;
                    }
                    if inf.avail_out == 0 {
                        if out_pos >= recovered.len() {
                            recovered.resize(recovered.len().saturating_add(1024).max(1024), 0);
                        }
                        inf.next_out = recovered[out_pos..].as_mut_ptr();
                        inf.avail_out = (recovered.len() - out_pos) as u32;
                    }

                    let rc = mz::mz_inflate(&mut inf as *mut _, 0);
                    last_inf_rc = rc;
                    digest = fold(digest, rc as u64);
                    out_pos = inf.total_out as usize;
                    if rc == 1 || rc < 0 {
                        break;
                    }
                    if in_pos >= comp.len() && inf.avail_in == 0 && rc == 0 && inf.avail_out != 0 {
                        break;
                    }
                }

                recovered.truncate(inf.total_out as usize);
                let _ = mz::mz_inflateEnd(&mut inf as *mut _);
            }

            let in_adler = mz::mz_adler32(
                1,
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr()
                },
                input.len(),
            );
            let in_crc = mz::mz_crc32(
                0,
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr()
                },
                input.len(),
            );
            let out_adler = mz::mz_adler32(
                1,
                if recovered.is_empty() {
                    ptr::null()
                } else {
                    recovered.as_ptr()
                },
                recovered.len(),
            );
            let out_crc = mz::mz_crc32(
                0,
                if recovered.is_empty() {
                    ptr::null()
                } else {
                    recovered.as_ptr()
                },
                recovered.len(),
            );
            last_err_strlen = cstr_len(mz::mz_error(last_inf_rc));

            digest = fold(digest, input.len() as u64);
            digest = fold(digest, comp.len() as u64);
            digest = fold(digest, recovered.len() as u64);
            digest = fold(digest, in_adler as u64);
            digest = fold(digest, in_crc as u64);
            digest = fold(digest, out_adler as u64);
            digest = fold(digest, out_crc as u64);
            digest = fold(digest, bytes_checksum(&recovered));
            digest = fold(digest, (input == recovered) as u64);
            digest = fold(digest, last_err_strlen);
        }
    }

    format!(
        "op=mz_stream_roundtrip def_rc={} inf_rc={} errlen={} digest={:016x}",
        last_def_rc, last_inf_rc, last_err_strlen, digest
    )
}

fn tinfl_decode_blob(input: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_cb_rc = 0i32;

    for _ in 0..iters {
        unsafe {
            let mut out_len_heap: usize = 0;
            let heap_ptr = tinfl::tinfl_decompress_mem_to_heap(
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr() as *const c_void
                },
                input.len(),
                &mut out_len_heap,
                1,
            );

            let mut heap_bytes: &[u8] = &[];
            if !heap_ptr.is_null() && out_len_heap != 0 {
                heap_bytes = slice::from_raw_parts(heap_ptr as *const u8, out_len_heap);
            }

            let cap_guess = if !heap_bytes.is_empty() {
                heap_bytes.len()
            } else {
                input
                    .len()
                    .saturating_mul(64)
                    .saturating_add(4096)
                    .min(64 * 1024 * 1024)
            };
            let mut mem_buf = vec![0u8; cap_guess];
            let mem_out = tinfl::tinfl_decompress_mem_to_mem(
                mem_buf.as_mut_ptr() as *mut c_void,
                mem_buf.len(),
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr() as *const c_void
                },
                input.len(),
                1,
            );

            let mem_ok = mem_out != usize::MAX && mem_out <= mem_buf.len();
            if mem_ok {
                mem_buf.truncate(mem_out);
            } else {
                mem_buf.clear();
            }

            let mut cb_in_size = input.len();
            let mut cb_state = TinflCbState::default();
            last_cb_rc = tinfl::tinfl_decompress_mem_to_callback(
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr() as *const c_void
                },
                &mut cb_in_size,
                Some(tinfl_put_cb),
                &mut cb_state as *mut _ as *mut c_void,
                1,
            );

            let heap_crc = mz::mz_crc32(
                0,
                if heap_bytes.is_empty() {
                    ptr::null()
                } else {
                    heap_bytes.as_ptr()
                },
                heap_bytes.len(),
            );
            let heap_adler = mz::mz_adler32(
                1,
                if heap_bytes.is_empty() {
                    ptr::null()
                } else {
                    heap_bytes.as_ptr()
                },
                heap_bytes.len(),
            );
            let mem_crc = mz::mz_crc32(
                0,
                if mem_buf.is_empty() {
                    ptr::null()
                } else {
                    mem_buf.as_ptr()
                },
                mem_buf.len(),
            );
            let mem_adler = mz::mz_adler32(
                1,
                if mem_buf.is_empty() {
                    ptr::null()
                } else {
                    mem_buf.as_ptr()
                },
                mem_buf.len(),
            );
            let cb_crc = mz::mz_crc32(
                0,
                if cb_state.buf.is_empty() {
                    ptr::null()
                } else {
                    cb_state.buf.as_ptr()
                },
                cb_state.buf.len(),
            );
            let cb_adler = mz::mz_adler32(
                1,
                if cb_state.buf.is_empty() {
                    ptr::null()
                } else {
                    cb_state.buf.as_ptr()
                },
                cb_state.buf.len(),
            );

            digest = fold(digest, input.len() as u64);
            digest = fold(digest, cb_in_size as u64);
            digest = fold(digest, out_len_heap as u64);
            digest = fold(digest, mem_out as u64);
            digest = fold(digest, last_cb_rc as u64);
            digest = fold(digest, heap_crc as u64);
            digest = fold(digest, heap_adler as u64);
            digest = fold(digest, mem_crc as u64);
            digest = fold(digest, mem_adler as u64);
            digest = fold(digest, cb_crc as u64);
            digest = fold(digest, cb_adler as u64);
            digest = fold(digest, cb_state.total);
            digest = fold(digest, cb_state.calls);
            digest = fold(digest, cb_state.digest);
            digest = fold(digest, (heap_bytes == mem_buf.as_slice()) as u64);
            digest = fold(digest, (heap_bytes == cb_state.buf.as_slice()) as u64);
            digest = fold(digest, bytes_checksum(heap_bytes));
            digest = fold(digest, bytes_checksum(&mem_buf));
            digest = fold(digest, bytes_checksum(&cb_state.buf));

            if !heap_ptr.is_null() {
                mz::mz_free(heap_ptr);
            }
        }
    }

    format!("op=tinfl_decode_blob cb_rc={} digest={:016x}", last_cb_rc, digest)
}

fn zip_mem_roundtrip(input: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_files = 0u64;
    let name1 = b"payload.bin\0";
    let name2 = b"mirror.dat\0";
    let comment2 = b"member-comment";

    for _ in 0..iters {
        let mut mirrored = Vec::with_capacity(input.len().saturating_add(16));
        mirrored.extend_from_slice(input);
        mirrored.extend_from_slice(b"::mirror::");
        mirrored.extend(input.iter().rev().take(input.len().min(128)));

        let members = [
            (input, name1.as_slice(), None),
            (mirrored.as_slice(), name2.as_slice(), Some(comment2.as_slice())),
        ];

        let archive = match build_zip_blob(&members) {
            Some(v) => v,
            None => {
                digest = fold(digest, 0);
                continue;
            }
        };

        unsafe {
            let mut za = MaybeUninit::<zip::mz_zip_archive>::zeroed();
            let pzip = za.as_mut_ptr();
            zip::mz_zip_zero_struct(pzip);

            let init_ok =
                zip::mz_zip_reader_init_mem(pzip, archive.as_ptr() as *const c_void, archive.len(), 0);
            digest = fold(digest, init_ok as u64);

            if init_ok != 0 {
                let num_files = zip::mz_zip_reader_get_num_files(pzip) as u64;
                last_files = num_files;
                digest = fold(digest, num_files);

                let loc1 =
                    zip::mz_zip_reader_locate_file(pzip, name1.as_ptr() as *const c_char, ptr::null(), 0);
                let mut idx2: u32 = 0;
                let loc2 = zip::mz_zip_reader_locate_file_v2(
                    pzip,
                    name2.as_ptr() as *const c_char,
                    ptr::null(),
                    0,
                    &mut idx2,
                );
                digest = fold(digest, loc1 as u64);
                digest = fold(digest, idx2 as u64);
                digest = fold(digest, loc2 as u64);

                let sup1 = if loc1 >= 0 {
                    zip::mz_zip_reader_is_file_supported(pzip, loc1 as u32)
                } else {
                    0
                };
                let dir1 = if loc1 >= 0 {
                    zip::mz_zip_reader_is_file_a_directory(pzip, loc1 as u32)
                } else {
                    0
                };
                digest = fold(digest, sup1 as u64);
                digest = fold(digest, dir1 as u64);

                let mut fname = vec![0i8; 256];
                let fname_len = if loc1 >= 0 {
                    zip::mz_zip_reader_get_filename(pzip, loc1 as u32, fname.as_mut_ptr(), fname.len() as u32)
                } else {
                    0
                };
                digest = fold(digest, fname_len as u64);

                let mut stat = MaybeUninit::<zip::mz_zip_archive_file_stat>::zeroed();
                let stat_ok = if loc1 >= 0 {
                    zip::mz_zip_reader_file_stat(pzip, loc1 as u32, stat.as_mut_ptr())
                } else {
                    0
                };
                digest = fold(digest, stat_ok as u64);

                let valid = zip::mz_zip_validate_archive(pzip, 0);
                digest = fold(digest, valid as u64);

                let mut out1 = vec![0u8; input.len().max(1)];
                let ex1 = if loc1 >= 0 {
                    zip::mz_zip_reader_extract_to_mem(
                        pzip,
                        loc1 as u32,
                        out1.as_mut_ptr() as *mut c_void,
                        out1.len(),
                        0,
                    )
                } else {
                    0
                };
                digest = fold(digest, ex1 as u64);
                if ex1 != 0 {
                    let crc1 = mz::mz_crc32(0, out1.as_ptr(), out1.len());
                    let ad1 = mz::mz_adler32(1, out1.as_ptr(), out1.len());
                    digest = fold(digest, crc1 as u64);
                    digest = fold(digest, ad1 as u64);
                    digest = fold(digest, bytes_checksum(&out1));
                }

                let mut out2_len: usize = 0;
                let out2_ptr = if loc2 != 0 {
                    zip::mz_zip_reader_extract_to_heap(pzip, idx2, &mut out2_len, 0)
                } else {
                    ptr::null_mut()
                };
                digest = fold(digest, out2_len as u64);
                if !out2_ptr.is_null() {
                    let out2 = slice::from_raw_parts(out2_ptr as *const u8, out2_len);
                    let crc2 = mz::mz_crc32(
                        0,
                        if out2.is_empty() { ptr::null() } else { out2.as_ptr() },
                        out2.len(),
                    );
                    let ad2 = mz::mz_adler32(
                        1,
                        if out2.is_empty() { ptr::null() } else { out2.as_ptr() },
                        out2.len(),
                    );
                    digest = fold(digest, crc2 as u64);
                    digest = fold(digest, ad2 as u64);
                    digest = fold(digest, bytes_checksum(out2));
                    mz::mz_free(out2_ptr);
                }

                let mut cb = ZipCbState::default();
                let ex_cb = if loc1 >= 0 {
                    zip::mz_zip_reader_extract_to_callback(
                        pzip,
                        loc1 as u32,
                        Some(zip_write_cb),
                        &mut cb as *mut _ as *mut c_void,
                        0,
                    )
                } else {
                    0
                };
                digest = fold(digest, ex_cb as u64);
                digest = fold(digest, cb.total);
                digest = fold(digest, cb.calls);
                digest = fold(digest, cb.digest);

                let _ = zip::mz_zip_reader_end(pzip);
                let _ = zip::mz_zip_end(pzip);
            } else {
                let _ = zip::mz_zip_end(pzip);
            }

            digest = fold(digest, archive.len() as u64);
            digest = fold(digest, mz::mz_crc32(0, archive.as_ptr(), archive.len()) as u64);
        }
    }

    format!("op=zip_mem_roundtrip files={} digest={:016x}", last_files, digest)
}

fn zip_reader_blob(input: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err_code = 0u64;

    let alpha = b"alpha.txt\0";
    let beta = b"beta.bin\0";
    let gamma = b"gamma/log.json\0";

    for _ in 0..iters {
        unsafe {
            let mut mem_err: zip::mz_zip_error = 0;
            let valid_mem = zip::mz_zip_validate_mem_archive(
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr() as *const c_void
                },
                input.len(),
                0,
                &mut mem_err,
            );
            digest = fold(digest, valid_mem as u64);
            digest = fold(digest, mem_err as u64);

            let mut za = MaybeUninit::<zip::mz_zip_archive>::zeroed();
            let pzip = za.as_mut_ptr();
            zip::mz_zip_zero_struct(pzip);

            let init_ok = zip::mz_zip_reader_init_mem(
                pzip,
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr() as *const c_void
                },
                input.len(),
                0,
            );
            digest = fold(digest, init_ok as u64);

            if init_ok != 0 {
                let valid = zip::mz_zip_validate_archive(pzip, 0);
                let num = zip::mz_zip_reader_get_num_files(pzip) as u64;
                let arch_sz = zip::mz_zip_get_archive_size(pzip);
                let cd_sz = zip::mz_zip_get_central_dir_size(pzip);
                let zip64 = zip::mz_zip_is_zip64(pzip);
                digest = fold(digest, valid as u64);
                digest = fold(digest, num);
                digest = fold(digest, arch_sz);
                digest = fold(digest, cd_sz as u64);
                digest = fold(digest, zip64 as u64);

                for name in [alpha.as_slice(), beta.as_slice(), gamma.as_slice()] {
                    let loc =
                        zip::mz_zip_reader_locate_file(pzip, name.as_ptr() as *const c_char, ptr::null(), 0);
                    let mut idx: u32 = 0;
                    let loc2 = zip::mz_zip_reader_locate_file_v2(
                        pzip,
                        name.as_ptr() as *const c_char,
                        ptr::null(),
                        0,
                        &mut idx,
                    );
                    digest = fold(digest, loc as u64);
                    digest = fold(digest, idx as u64);
                    digest = fold(digest, loc2 as u64);

                    let found = loc >= 0 || loc2 != 0;
                    if !found {
                        continue;
                    }

                    let qidx = if loc >= 0 { loc as u32 } else { idx };
                    let enc = zip::mz_zip_reader_is_file_encrypted(pzip, qidx);
                    let sup = zip::mz_zip_reader_is_file_supported(pzip, qidx);
                    let dir = zip::mz_zip_reader_is_file_a_directory(pzip, qidx);
                    digest = fold(digest, enc as u64);
                    digest = fold(digest, sup as u64);
                    digest = fold(digest, dir as u64);

                    let mut fname = vec![0i8; 256];
                    let fnlen =
                        zip::mz_zip_reader_get_filename(pzip, qidx, fname.as_mut_ptr(), fname.len() as u32);
                    digest = fold(digest, fnlen as u64);

                    let mut stat = MaybeUninit::<zip::mz_zip_archive_file_stat>::zeroed();
                    let stok = zip::mz_zip_reader_file_stat(pzip, qidx, stat.as_mut_ptr());
                    digest = fold(digest, stok as u64);

                    let buf_cap = input
                        .len()
                        .saturating_mul(16)
                        .saturating_add(4096)
                        .min(64 * 1024 * 1024)
                        .max(1);
                    let mut mem_buf = vec![0u8; buf_cap];
                    let exm = zip::mz_zip_reader_extract_to_mem(
                        pzip,
                        qidx,
                        mem_buf.as_mut_ptr() as *mut c_void,
                        mem_buf.len(),
                        0,
                    );
                    digest = fold(digest, exm as u64);
                    if exm != 0 {
                        let crc = mz::mz_crc32(0, mem_buf.as_ptr(), mem_buf.len());
                        digest = fold(digest, crc as u64);
                        digest = fold(digest, bytes_checksum(&mem_buf));
                    }

                    let mut heap_len: usize = 0;
                    let heap_ptr = zip::mz_zip_reader_extract_to_heap(pzip, qidx, &mut heap_len, 0);
                    digest = fold(digest, heap_len as u64);
                    if !heap_ptr.is_null() {
                        let heap = slice::from_raw_parts(heap_ptr as *const u8, heap_len);
                        let crc = mz::mz_crc32(
                            0,
                            if heap.is_empty() { ptr::null() } else { heap.as_ptr() },
                            heap.len(),
                        );
                        digest = fold(digest, crc as u64);
                        digest = fold(digest, bytes_checksum(heap));
                        mz::mz_free(heap_ptr);
                    }

                    let iter = zip::mz_zip_reader_extract_iter_new(pzip, qidx, 0);
                    digest = fold(digest, iter.is_null() as u64);
                    if !iter.is_null() {
                        let mut total_iter = 0u64;
                        let mut buf = vec![0u8; 1024];
                        loop {
                            let n = zip::mz_zip_reader_extract_iter_read(
                                iter,
                                buf.as_mut_ptr() as *mut c_void,
                                buf.len(),
                            );
                            if n == 0 {
                                break;
                            }
                            total_iter = total_iter.wrapping_add(n as u64);
                            digest = fold(digest, bytes_checksum(&buf[..n]));
                        }
                        digest = fold(digest, total_iter);
                        let fr = zip::mz_zip_reader_extract_iter_free(iter);
                        digest = fold(digest, fr as u64);
                    }
                }

                last_err_code = zip::mz_zip_get_last_error(pzip) as u64;
                digest = fold(digest, last_err_code);
                digest = fold(digest, cstr_len(zip::mz_zip_get_error_string(last_err_code as _)));

                let _ = zip::mz_zip_reader_end(pzip);
                let _ = zip::mz_zip_end(pzip);
            } else {
                let e = zip::mz_zip_get_last_error(pzip) as u64;
                last_err_code = e;
                digest = fold(digest, e);
                digest = fold(digest, cstr_len(zip::mz_zip_get_error_string(e as _)));
                let _ = zip::mz_zip_end(pzip);
            }
        }
    }

    format!("op=zip_reader_blob err={} digest={:016x}", last_err_code, digest)
}

pub fn ops() -> Vec<(&'static str, fn(&[u8], u64) -> String)> {
    vec![
