pub fn gen_seeds(dir: &str) -> Vec<String> {
    let _ = fs::create_dir_all(dir);
    let mut lines = Vec::new();

    let raw1 = make_text_payload(160);
    let raw2 = make_mixed_payload(150);

    for (op, idx, bytes) in [
        ("mz_stream_roundtrip", 1usize, raw1.as_slice()),
        ("mz_stream_roundtrip", 2usize, raw2.as_slice()),
        ("zip_mem_roundtrip", 1usize, raw1.as_slice()),
        ("zip_mem_roundtrip", 2usize, raw2.as_slice()),
    ] {
        let path = format!("{}/{}.{}.bin", dir, op, idx);
        if write_file(&path, bytes) {
            lines.push(format!("seed {} {}", op, path));
        }
    }

    let comp1 = compress_zlib_blob(&raw1, 6)
        .unwrap_or_else(|| Vec::from(&b"x\x9c\x03\x00\x00\x00\x00\x01"[..]));
    let comp2 = compress_zlib_blob(&raw2, 6)
        .unwrap_or_else(|| Vec::from(&b"x\x9c\x03\x00\x00\x00\x00\x01"[..]));
    for (idx, bytes) in [(1usize, comp1.as_slice()), (2usize, comp2.as_slice())] {
        let path = format!("{}/tinfl_decode_blob.{}.bin", dir, idx);
        if write_file(&path, bytes) {
            lines.push(format!("seed tinfl_decode_blob {}", path));
        }
    }

    let z1_members = [
        (
            raw1[..raw1.len().min(4096)].as_ref(),
            b"alpha.txt\0".as_slice(),
            None,
        ),
        (
            raw2[..raw2.len().min(2048)].as_ref(),
            b"beta.bin\0".as_slice(),
            Some(b"beta-comment".as_slice()),
        ),
        (
            raw1[..raw1.len().min(1024)].as_ref(),
            b"gamma/log.json\0".as_slice(),
            Some(b"gamma-comment".as_slice()),
        ),
    ];
    let z2_members = [
        (
            raw2[..raw2.len().min(3500)].as_ref(),
            b"alpha.txt\0".as_slice(),
            None,
        ),
        (
            raw1[..raw1.len().min(2800)].as_ref(),
            b"beta.bin\0".as_slice(),
            Some(b"beta-comment-2".as_slice()),
        ),
        (
            raw2[..raw2.len().min(1500)].as_ref(),
            b"gamma/log.json\0".as_slice(),
            Some(b"gamma-comment-2".as_slice()),
        ),
    ];

    let zip1 = build_zip_blob(&z1_members).or_else(|| {
        build_zip_blob(&[
            (b"seed alpha\n".as_ref(), b"alpha.txt\0".as_slice(), None),
            (b"\x00\x01\x02seed-beta".as_ref(), b"beta.bin\0".as_slice(), None),
            (b"{\"k\":\"v1\"}\n".as_ref(), b"gamma/log.json\0".as_slice(), None),
        ])
    });
    let zip2 = build_zip_blob(&z2_members).or_else(|| {
        build_zip_blob(&[
            (
                b"another deterministic alpha payload\n".as_ref(),
                b"alpha.txt\0".as_slice(),
                None,
            ),
            (
                b"\x10\x20\x30\x40different-beta".as_ref(),
                b"beta.bin\0".as_slice(),
                None,
            ),
            (
                b"{\"k\":\"v2\",\"n\":2}\n".as_ref(),
                b"gamma/log.json\0".as_slice(),
                None,
            ),
        ])
    });

    if let Some(bytes) = zip1 {
        let path = format!("{}/zip_reader_blob.1.bin", dir);
        if write_file(&path, &bytes) {
            lines.push(format!("seed zip_reader_blob {}", path));
        }
    }
    if let Some(bytes) = zip2 {
        let path = format!("{}/zip_reader_blob.2.bin", dir);
        if write_file(&path, &bytes) {
            lines.push(format!("seed zip_reader_blob {}", path));
        }
    }

    lines
}

pub fn gen_perf(dir: &str) -> Vec<String> {
    let _ = fs::create_dir_all(dir);
    let mut lines = Vec::new();

    let raw = make_perf_payload();

    let p1 = format!("{}/mz_stream_roundtrip.perf.bin", dir);
    if write_file(&p1, &raw) {
        lines.push(format!("perf mz_stream_roundtrip {}", p1));
    }

    let p2 = format!("{}/zip_mem_roundtrip.perf.bin", dir);
    if write_file(&p2, &raw) {
        lines.push(format!("perf zip_mem_roundtrip {}", p2));
    }

    if let Some(comp) = compress_zlib_blob(&raw, 6) {
        let p3 = format!("{}/tinfl_decode_blob.perf.bin", dir);
        if write_file(&p3, &comp) {
