unsafe extern "C" fn read_buf_cb(
    opaque: *mut c_void,
    file_ofs: zip::mz_uint64,
    p_buf: *mut c_void,
    n: usize,
) -> usize {
    let st = &mut *(opaque as *mut ReadBufState);
    let start = (file_ofs as usize).min(st.data.len());
    let end = start.saturating_add(n).min(st.data.len());
    let amt = end.saturating_sub(start);
    st.calls = st.calls.wrapping_add(1);
    st.total = st.total.wrapping_add(amt as u64);
    st.digest = fold(st.digest, file_ofs);
    if amt != 0 && !p_buf.is_null() {
        ptr::copy_nonoverlapping(st.data[start..end].as_ptr(), p_buf as *mut u8, amt);
        st.digest = fold(st.digest, bytes_checksum(&st.data[start..end]));
    }
    amt
}

