            let mut def = MaybeUninit::<mz::mz_stream>::zeroed().assume_init();
            let mut comp: Vec<u8> = Vec::new();
            let mut recovered: Vec<u8> = Vec::new();

            let init_rc = mz::mz_deflateInit2(&mut def as *mut _, 6, 8, 15, 9, 0);
