            digest = fold(digest, cb_state.digest);
            digest = fold(digest, (heap_bytes == mem_buf.as_slice()) as u64);
            digest = fold(digest, (heap_bytes == cb_state.buf.as_slice()) as u64);
            digest = fold(digest, bytes_checksum(heap_bytes));
            digest = fold(digest, bytes_checksum(&mem_buf));
            digest = fold(digest, bytes_checksum(&cb_state.buf));

            if !heap_ptr.is_null() {
                mz::mz_free(heap_ptr);
            }
        }
    }

    format!("op=tinfl_decode_blob cb_rc={} digest={:016x}", last_cb_rc, digest)
}

fn tdefl_encode_blob(input: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_status = 0i32;

    for _ in 0..iters {
        unsafe {
            let flags = tdef::tdefl_create_comp_flags_from_zip_params(6, 15, 0) as i32;

            let comp = tdef::tdefl_compressor_alloc();
            digest = fold(digest, comp.is_null() as u64);
            if !comp.is_null() {
                let mut cb = TdeflCbState::default();
                let init_st = tdef::tdefl_init(comp, Some(tdefl_put_cb), &mut cb as *mut _ as *mut c_void, flags);
                digest = fold(digest, init_st as u64);

                let mut in_sz = input.len();
                let mut out_buf = vec![0u8; mz::mz_compressBound(input.len() as mz::mz_ulong) as usize + 64];
                let mut out_sz = out_buf.len();
                let st = tdef::tdefl_compress(
                    comp,
                    if input.is_empty() { ptr::null() } else { input.as_ptr() as *const c_void },
                    &mut in_sz,
                    out_buf.as_mut_ptr() as *mut c_void,
                    &mut out_sz,
                    4,
                );
                last_status = st as i32;
                digest = fold(digest, st as u64);
                digest = fold(digest, in_sz as u64);
                digest = fold(digest, out_sz as u64);
                if out_sz <= out_buf.len() {
                    digest = fold(digest, bytes_checksum(&out_buf[..out_sz]));
                }

                let prev = tdef::tdefl_get_prev_return_status(comp);
                let ad = tdef::tdefl_get_adler32(comp);
                digest = fold(digest, prev as u64);
                digest = fold(digest, ad as u64);
                digest = fold(digest, cb.total);
                digest = fold(digest, cb.calls);
                digest = fold(digest, cb.digest);
                digest = fold(digest, bytes_checksum(&cb.buf));

                tdef::tdefl_compressor_free(comp);
            }

            let mut heap_len = 0usize;
            let heap_ptr = tdef::tdefl_compress_mem_to_heap(
                if input.is_empty() { ptr::null() } else { input.as_ptr() as *const c_void },
                input.len(),
                &mut heap_len,
                flags,
            );
            digest = fold(digest, heap_len as u64);
            if !heap_ptr.is_null() {
                let heap = slice::from_raw_parts(heap_ptr as *const u8, heap_len);
                digest = fold(digest, bytes_checksum(heap));
                mz::mz_free(heap_ptr);
            }

            let mut mem = vec![0u8; mz::mz_compressBound(input.len() as mz::mz_ulong) as usize + 64];
            let mem_len = tdef::tdefl_compress_mem_to_mem(
                mem.as_mut_ptr() as *mut c_void,
                mem.len(),
                if input.is_empty() { ptr::null() } else { input.as_ptr() as *const c_void },
                input.len(),
                flags,
            );
            digest = fold(digest, mem_len as u64);
            if mem_len != usize::MAX && mem_len <= mem.len() {
                digest = fold(digest, bytes_checksum(&mem[..mem_len]));
            }

            let mut cb2 = TdeflCbState::default();
            let ok = tdef::tdefl_compress_mem_to_output(
                if input.is_empty() { ptr::null() } else { input.as_ptr() as *const c_void },
                input.len(),
                Some(tdefl_put_cb),
                &mut cb2 as *mut _ as *mut c_void,
                flags,
            );
            digest = fold(digest, ok as u64);
            digest = fold(digest, cb2.total);
            digest = fold(digest, cb2.calls);
            digest = fold(digest, cb2.digest);
            digest = fold(digest, bytes_checksum(&cb2.buf));

            let w = 16i32;
            let h = ((input.len() / 64).max(1).min(64)) as i32;
            let need = (w as usize) * (h as usize) * 4;
            let mut img = vec![0u8; need];
            for i in 0..need {
                img[i] = input.get(i % input.len().max(1)).copied().unwrap_or(0).wrapping_add(i as u8);
            }

            let mut png_len1 = 0usize;
            let png1 = tdef::tdefl_write_image_to_png_file_in_memory(
                img.as_ptr() as *const c_void,
                w,
                h,
                4,
                &mut png_len1,
            );
            digest = fold(digest, png_len1 as u64);
            if !png1.is_null() {
                let png = slice::from_raw_parts(png1 as *const u8, png_len1);
                digest = fold(digest, bytes_checksum(png));
                mz::mz_free(png1);
            }

            let mut png_len2 = 0usize;
            let png2 = tdef::tdefl_write_image_to_png_file_in_memory_ex(
                img.as_ptr() as *const c_void,
                w,
                h,
                4,
                &mut png_len2,
                6,
                1,
            );
            digest = fold(digest, png_len2 as u64);
            if !png2.is_null() {
                let png = slice::from_raw_parts(png2 as *const u8, png_len2);
                digest = fold(digest, bytes_checksum(png));
                mz::mz_free(png2);
            }
        }
    }

    format!("op=tdefl_encode_blob status={} digest={:016x}", last_status, digest)
}

fn zip_mem_roundtrip(input: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_files = 0u64;
    let name1 = b"payload.bin\0";
    let name2 = b"mirror.dat\0";
    let comment2 = b"member-comment";

    for _ in 0..iters {
        let mut mirrored = Vec::with_capacity(input.len().saturating_add(16));
        mirrored.extend_from_slice(input);
        mirrored.extend_from_slice(b"::mirror::");
        mirrored.extend(input.iter().rev().take(input.len().min(128)));

        let members = [
            (input, name1.as_slice(), None),
            (mirrored.as_slice(), name2.as_slice(), Some(comment2.as_slice())),
        ];

        let archive = match build_zip_blob(&members) {
            Some(v) => v,
            None => {
                digest = fold(digest, 0);
                continue;
            }
        };

        unsafe {
            let mut za = MaybeUninit::<zip::mz_zip_archive>::zeroed();
            let pzip = za.as_mut_ptr();
            zip::mz_zip_zero_struct(pzip);

            let init_ok = zip::mz_zip_reader_init_mem(
                pzip,
                archive.as_ptr() as *const c_void,
                archive.len(),
                0,
            );
            digest = fold(digest, init_ok as u64);

            if init_ok != 0 {
                digest = fold(digest, zip::mz_zip_get_mode(pzip) as u64);
                digest = fold(digest, zip::mz_zip_get_type(pzip) as u64);
                digest = fold(digest, zip::mz_zip_get_archive_file_start_offset(pzip));
                digest = fold(digest, zip::mz_zip_get_cfile(pzip).is_null() as u64);

                let num_files = zip::mz_zip_reader_get_num_files(pzip) as u64;
                last_files = num_files;
                digest = fold(digest, num_files);

                let loc1 = zip::mz_zip_reader_locate_file(
                    pzip,
                    name1.as_ptr() as *const c_char,
                    ptr::null(),
                    0,
                );
                let mut idx2: u32 = 0;
                let loc2 = zip::mz_zip_reader_locate_file_v2(
                    pzip,
                    name2.as_ptr() as *const c_char,
                    ptr::null(),
                    0,
                    &mut idx2,
                );
                digest = fold(digest, loc1 as u64);
                digest = fold(digest, idx2 as u64);
                digest = fold(digest, loc2 as u64);

                let sup1 = if loc1 >= 0 {
                    zip::mz_zip_reader_is_file_supported(pzip, loc1 as u32)
                } else {
                    0
                };
                let dir1 = if loc1 >= 0 {
                    zip::mz_zip_reader_is_file_a_directory(pzip, loc1 as u32)
                } else {
                    0
                };
                digest = fold(digest, sup1 as u64);
                digest = fold(digest, dir1 as u64);

                let mut fname = vec![0i8; 256];
                let fname_len = if loc1 >= 0 {
                    zip::mz_zip_reader_get_filename(
                        pzip,
                        loc1 as u32,
                        fname.as_mut_ptr(),
                        fname.len() as u32,
                    )
                } else {
                    0
                };
                digest = fold(digest, fname_len as u64);

                let mut stat = MaybeUninit::<zip::mz_zip_archive_file_stat>::zeroed();
                let stat_ok = if loc1 >= 0 {
                    zip::mz_zip_reader_file_stat(pzip, loc1 as u32, stat.as_mut_ptr())
                } else {
                    0
                };
                digest = fold(digest, stat_ok as u64);

                let valid = zip::mz_zip_validate_archive(pzip, 0);
                digest = fold(digest, valid as u64);

                let mut hdr = vec![0u8; archive.len().min(64).max(1)];
                let rd = zip::mz_zip_read_archive_data(
                    pzip,
                    0,
                    hdr.as_mut_ptr() as *mut c_void,
                    hdr.len(),
                );
                digest = fold(digest, rd as u64);
                digest = fold(digest, bytes_checksum(&hdr[..rd.min(hdr.len())]));

                let mut out1 = vec![0u8; input.len().max(1)];
                let ex1 = if loc1 >= 0 {
                    zip::mz_zip_reader_extract_to_mem(
                        pzip,
                        loc1 as u32,
                        out1.as_mut_ptr() as *mut c_void,
                        out1.len(),
                        0,
                    )
                } else {
                    0
                };
                digest = fold(digest, ex1 as u64);
                if ex1 != 0 {
                    let crc1 = mz::mz_crc32(0, out1.as_ptr(), out1.len());
                    let ad1 = mz::mz_adler32(1, out1.as_ptr(), out1.len());
                    digest = fold(digest, crc1 as u64);
                    digest = fold(digest, ad1 as u64);
                    digest = fold(digest, bytes_checksum(&out1));
                }

                let mut out2_len: usize = 0;
                let out2_ptr = if loc2 != 0 {
                    zip::mz_zip_reader_extract_to_heap(pzip, idx2, &mut out2_len, 0)
                } else {
                    ptr::null_mut()
                };
                digest = fold(digest, out2_len as u64);
                if !out2_ptr.is_null() {
                    let out2 = slice::from_raw_parts(out2_ptr as *const u8, out2_len);
                    let crc2 = mz::mz_crc32(
                        0,
                        if out2.is_empty() { ptr::null() } else { out2.as_ptr() },
                        out2.len(),
                    );
                    let ad2 = mz::mz_adler32(
                        1,
                        if out2.is_empty() { ptr::null() } else { out2.as_ptr() },
                        out2.len(),
                    );
                    digest = fold(digest, crc2 as u64);
                    digest = fold(digest, ad2 as u64);
                    digest = fold(digest, bytes_checksum(out2));
                    mz::mz_free(out2_ptr);
                }

                let mut cb = ZipCbState::default();
                let ex_cb = if loc1 >= 0 {
                    zip::mz_zip_reader_extract_to_callback(
                        pzip,
                        loc1 as u32,
                        Some(zip_write_cb),
                        &mut cb as *mut _ as *mut c_void,
                        0,
                    )
                } else {
                    0
                };
                digest = fold(digest, ex_cb as u64);
                digest = fold(digest, cb.total);
                digest = fold(digest, cb.calls);
                digest = fold(digest, cb.digest);

                let _ = zip::mz_zip_reader_end(pzip);
                let _ = zip::mz_zip_end(pzip);
            } else {
                let _ = zip::mz_zip_end(pzip);
            }

            digest = fold(digest, archive.len() as u64);
            digest = fold(digest, mz::mz_crc32(0, archive.as_ptr(), archive.len()) as u64);
        }
    }

    format!("op=zip_mem_roundtrip files={} digest={:016x}", last_files, digest)
}

fn zip_reader_blob(input: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err_code = 0u64;

    let alpha = b"alpha.txt\0";
    let beta = b"beta.bin\0";
    let gamma = b"gamma/log.json\0";

    for _ in 0..iters {
        unsafe {
            let mut mem_err: zip::mz_zip_error = 0;
            let valid_mem = zip::mz_zip_validate_mem_archive(
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr() as *const c_void
                },
                input.len(),
                0,
                &mut mem_err,
            );
            digest = fold(digest, valid_mem as u64);
            digest = fold(digest, mem_err as u64);

            let mut za = MaybeUninit::<zip::mz_zip_archive>::zeroed();
            let pzip = za.as_mut_ptr();
            zip::mz_zip_zero_struct(pzip);

            let init_ok = zip::mz_zip_reader_init_mem(
                pzip,
                if input.is_empty() {
                    ptr::null()
                } else {
                    input.as_ptr() as *const c_void
                },
                input.len(),
                0,
            );
            digest = fold(digest, init_ok as u64);

            if init_ok != 0 {
                digest = fold(digest, zip::mz_zip_get_mode(pzip) as u64);
                digest = fold(digest, zip::mz_zip_get_type(pzip) as u64);
                digest = fold(digest, zip::mz_zip_get_archive_file_start_offset(pzip));
                digest = fold(digest, zip::mz_zip_get_cfile(pzip).is_null() as u64);

                let valid = zip::mz_zip_validate_archive(pzip, 0);
                let num = zip::mz_zip_reader_get_num_files(pzip) as u64;
                let arch_sz = zip::mz_zip_get_archive_size(pzip);
                let cd_sz = zip::mz_zip_get_central_dir_size(pzip);
                let zip64 = zip::mz_zip_is_zip64(pzip);
                digest = fold(digest, valid as u64);
                digest = fold(digest, num);
                digest = fold(digest, arch_sz);
                digest = fold(digest, cd_sz as u64);
                digest = fold(digest, zip64 as u64);

                let mut hdr = vec![0u8; input.len().min(128).max(1)];
                let rd = zip::mz_zip_read_archive_data(
                    pzip,
                    0,
                    hdr.as_mut_ptr() as *mut c_void,
                    hdr.len(),
                );
                digest = fold(digest, rd as u64);
                digest = fold(digest, bytes_checksum(&hdr[..rd.min(hdr.len())]));

                let _ = zip::mz_zip_set_last_error(pzip, mem_err);
                digest = fold(digest, zip::mz_zip_peek_last_error(pzip) as u64);
                let _ = zip::mz_zip_clear_last_error(pzip);
                digest = fold(digest, zip::mz_zip_peek_last_error(pzip) as u64);

                for name in [alpha.as_slice(), beta.as_slice(), gamma.as_slice()] {
                    let loc = zip::mz_zip_reader_locate_file(
                        pzip,
                        name.as_ptr() as *const c_char,
                        ptr::null(),
                        0,
                    );
                    let mut idx: u32 = 0;
                    let loc2 = zip::mz_zip_reader_locate_file_v2(
                        pzip,
                        name.as_ptr() as *const c_char,
                        ptr::null(),
                        0,
                        &mut idx,
                    );
                    digest = fold(digest, loc as u64);
                    digest = fold(digest, idx as u64);
                    digest = fold(digest, loc2 as u64);

                    let found = loc >= 0 || loc2 != 0;
                    if !found {
                        continue;
                    }

                    let qidx = if loc >= 0 { loc as u32 } else { idx };
                    let enc = zip::mz_zip_reader_is_file_encrypted(pzip, qidx);
                    let sup = zip::mz_zip_reader_is_file_supported(pzip, qidx);
                    let dir = zip::mz_zip_reader_is_file_a_directory(pzip, qidx);
                    let vf = zip::mz_zip_validate_file(pzip, qidx, 0);
                    digest = fold(digest, enc as u64);
                    digest = fold(digest, sup as u64);
                    digest = fold(digest, dir as u64);
                    digest = fold(digest, vf as u64);

                    let mut fname = vec![0i8; 256];
                    let fnlen = zip::mz_zip_reader_get_filename(
                        pzip,
                        qidx,
                        fname.as_mut_ptr(),
                        fname.len() as u32,
                    );
                    digest = fold(digest, fnlen as u64);

                    let mut stat = MaybeUninit::<zip::mz_zip_archive_file_stat>::zeroed();
                    let stok = zip::mz_zip_reader_file_stat(pzip, qidx, stat.as_mut_ptr());
                    digest = fold(digest, stok as u64);

                    let buf_cap = input
                        .len()
                        .saturating_mul(16)
                        .saturating_add(4096)
                        .min(64 * 1024 * 1024)
                        .max(1);
                    let mut mem_buf = vec![0u8; buf_cap];
                    let exm = zip::mz_zip_reader_extract_to_mem(
                        pzip,
                        qidx,
                        mem_buf.as_mut_ptr() as *mut c_void,
                        mem_buf.len(),
                        0,
                    );
                    digest = fold(digest, exm as u64);
                    if exm != 0 {
                        let crc = mz::mz_crc32(0, mem_buf.as_ptr(), mem_buf.len());
                        digest = fold(digest, crc as u64);
                        digest = fold(digest, bytes_checksum(&mem_buf));
                    }

                    let mut heap_len: usize = 0;
                    let heap_ptr = zip::mz_zip_reader_extract_to_heap(pzip, qidx, &mut heap_len, 0);
                    digest = fold(digest, heap_len as u64);
                    if !heap_ptr.is_null() {
                        let heap = slice::from_raw_parts(heap_ptr as *const u8, heap_len);
                        let crc = mz::mz_crc32(
                            0,
                            if heap.is_empty() { ptr::null() } else { heap.as_ptr() },
                            heap.len(),
                        );
                        digest = fold(digest, crc as u64);
                        digest = fold(digest, bytes_checksum(heap));
                        mz::mz_free(heap_ptr);
                    }

                    let iter = zip::mz_zip_reader_extract_iter_new(pzip, qidx, 0);
                    digest = fold(digest, iter.is_null() as u64);
                    if !iter.is_null() {
                        let mut total_iter = 0u64;
                        let mut buf = vec![0u8; 1024];
                        loop {
                            let n = zip::mz_zip_reader_extract_iter_read(
                                iter,
                                buf.as_mut_ptr() as *mut c_void,
                                buf.len(),
                            );
                            if n == 0 {
                                break;
                            }
                            total_iter = total_iter.wrapping_add(n as u64);
                            digest = fold(digest, bytes_checksum(&buf[..n]));
                        }
                        digest = fold(digest, total_iter);
                        let fr = zip::mz_zip_reader_extract_iter_free(iter);
                        digest = fold(digest, fr as u64);
                    }

                    let iter2 = zip::mz_zip_reader_extract_file_iter_new(
                        pzip,
                        name.as_ptr() as *const c_char,
                        0,
                    );
                    digest = fold(digest, iter2.is_null() as u64);
                    if !iter2.is_null() {
                        let mut total_iter = 0u64;
                        let mut buf = vec![0u8; 333];
                        loop {
                            let n = zip::mz_zip_reader_extract_iter_read(
                                iter2,
                                buf.as_mut_ptr() as *mut c_void,
                                buf.len(),
                            );
                            if n == 0 {
                                break;
                            }
                            total_iter = total_iter.wrapping_add(n as u64);
                            digest = fold(digest, bytes_checksum(&buf[..n]));
                        }
                        digest = fold(digest, total_iter);
                        let fr = zip::mz_zip_reader_extract_iter_free(iter2);
                        digest = fold(digest, fr as u64);
                    }

                    let mut no_alloc = vec![0u8; buf_cap];
                    let mut user_buf = vec![0u8; 8192];
                    let exna = zip::mz_zip_reader_extract_to_mem_no_alloc(
                        pzip,
                        qidx,
                        no_alloc.as_mut_ptr() as *mut c_void,
                        no_alloc.len(),
                        0,
                        user_buf.as_mut_ptr() as *mut c_void,
                        user_buf.len(),
                    );
                    digest = fold(digest, exna as u64);

                    let exf_mem = zip::mz_zip_reader_extract_file_to_mem(
                        pzip,
                        name.as_ptr() as *const c_char,
                        no_alloc.as_mut_ptr() as *mut c_void,
                        no_alloc.len(),
                        0,
                    );
                    digest = fold(digest, exf_mem as u64);

                    let exf_na = zip::mz_zip_reader_extract_file_to_mem_no_alloc(
                        pzip,
                        name.as_ptr() as *const c_char,
                        no_alloc.as_mut_ptr() as *mut c_void,
                        no_alloc.len(),
                        0,
                        user_buf.as_mut_ptr() as *mut c_void,
                        user_buf.len(),
                    );
                    digest = fold(digest, exf_na as u64);

                    let mut heap2_len = 0usize;
                    let heap2 = zip::mz_zip_reader_extract_file_to_heap(
                        pzip,
                        name.as_ptr() as *const c_char,
                        &mut heap2_len,
                        0,
                    );
                    digest = fold(digest, heap2_len as u64);
                    if !heap2.is_null() {
                        let h = slice::from_raw_parts(heap2 as *const u8, heap2_len);
                        digest = fold(digest, bytes_checksum(h));
                        mz::mz_free(heap2);
                    }

                    let mut cb = ZipCbState::default();
                    let exf_cb = zip::mz_zip_reader_extract_file_to_callback(
                        pzip,
                        name.as_ptr() as *const c_char,
                        Some(zip_write_cb),
                        &mut cb as *mut _ as *mut c_void,
                        0,
                    );
                    digest = fold(digest, exf_cb as u64);
                    digest = fold(digest, cb.total);
                    digest = fold(digest, cb.calls);
                    digest = fold(digest, cb.digest);
                }

                last_err_code = zip::mz_zip_get_last_error(pzip) as u64;
                digest = fold(digest, last_err_code);
                digest = fold(digest, cstr_len(zip::mz_zip_get_error_string(last_err_code as _)));

                let _ = zip::mz_zip_reader_end(pzip);
                let _ = zip::mz_zip_end(pzip);
            } else {
                let e = zip::mz_zip_get_last_error(pzip) as u64;
                last_err_code = e;
                digest = fold(digest, e);
                digest = fold(digest, cstr_len(zip::mz_zip_get_error_string(e as _)));
                let _ = zip::mz_zip_end(pzip);
            }
        }
    }

    format!("op=zip_reader_blob err={} digest={:016x}", last_err_code, digest)
}

fn zip_file_ops(input: &[u8], iters: u64) -> String {
    let mut digest = 0u64;
    let mut last_err = 0u64;

    for i in 0..iters {
        let base = format!("miniz_raw_harness_{}_{}", input.len(), i);
        let dir = std::env::temp_dir().join(base);
        let _ = fs::create_dir_all(&dir);

        let zip_path = dir.join("archive.zip");
        let src_path = dir.join("src.bin");
        let out1_path = dir.join("out1.bin");
        let out2_path = dir.join("out2.bin");
        let out3_path = dir.join("out3.bin");

        let _ = fs::write(&src_path, input);

        unsafe {
            let c_zip = CString::new(zip_path.to_string_lossy().as_bytes()).ok();
            let c_src = CString::new(src_path.to_string_lossy().as_bytes()).ok();
            let c_out1 = CString::new(out1_path.to_string_lossy().as_bytes()).ok();
            let c_out2 = CString::new(out2_path.to_string_lossy().as_bytes()).ok();
            let c_out3 = CString::new(out3_path.to_string_lossy().as_bytes()).ok();
            let c_arc1 = CString::new("alpha.txt").ok();
            let c_arc2 = CString::new("beta.bin").ok();
            let c_arc3 = CString::new("cb.dat").ok();

            if c_zip.is_none()
                || c_src.is_none()
                || c_out1.is_none()
                || c_out2.is_none()
                || c_out3.is_none()
                || c_arc1.is_none()
                || c_arc2.is_none()
                || c_arc3.is_none()
            {
                digest = fold(digest, 1);
                continue;
            }

            let c_zip = c_zip.unwrap();
            let c_src = c_src.unwrap();
            let c_out1 = c_out1.unwrap();
            let c_out2 = c_out2.unwrap();
            let c_out3 = c_out3.unwrap();
            let c_arc1 = c_arc1.unwrap();
            let c_arc2 = c_arc2.unwrap();
            let c_arc3 = c_arc3.unwrap();

            let mut za = MaybeUninit::<zip::mz_zip_archive>::zeroed();
            let pzip = za.as_mut_ptr();
            zip::mz_zip_zero_struct(pzip);

            let winit = zip::mz_zip_writer_init_file_v2(pzip, c_zip.as_ptr(), 0, 0);
            digest = fold(digest, winit as u64);
            if winit != 0 {
                digest = fold(digest, zip::mz_zip_get_mode(pzip) as u64);
                digest = fold(digest, zip::mz_zip_get_type(pzip) as u64);

                let addf = zip::mz_zip_writer_add_file(
                    pzip,
                    c_arc1.as_ptr(),
                    c_src.as_ptr(),
                    ptr::null(),
                    0,
                    6,
                );
                digest = fold(digest, addf as u64);

                let addm = zip::mz_zip_writer_add_mem_ex_v2(
                    pzip,
                    c_arc2.as_ptr(),
                    if input.is_empty() { ptr::null() } else { input.as_ptr() as *const c_void },
                    input.len(),
                    b"comment\0".as_ptr() as *const c_void,
                    7,
                    6,
                    0,
                    0,
                    ptr::null_mut(),
                    ptr::null(),
                    0,
                    ptr::null(),
                    0,
                );
                digest = fold(digest, addm as u64);

                let mut rstate = ReadBufState {
                    data: input,
                    total: 0,
                    calls: 0,
                    digest: 0,
                };
                let addcb = zip::mz_zip_writer_add_read_buf_callback(
                    pzip,
                    c_arc3.as_ptr(),
                    Some(read_buf_cb),
                    &mut rstate as *mut _ as *mut c_void,
                    input.len() as u64,
                    ptr::null(),
                    ptr::null(),
                    0,
                    6,
                    ptr::null(),
                    0,
                    ptr::null(),
                    0,
                );
                digest = fold(digest, addcb as u64);
                digest = fold(digest, rstate.total);
                digest = fold(digest, rstate.calls);
                digest = fold(digest, rstate.digest);

                let fin = zip::mz_zip_writer_finalize_archive(pzip);
                digest = fold(digest, fin as u64);
                let _ = zip::mz_zip_writer_end(pzip);
            } else {
                let _ = zip::mz_zip_writer_end(pzip);
            }

            let mut verr: zip::mz_zip_error = 0;
            let vfa = zip::mz_zip_validate_file_archive(c_zip.as_ptr(), 0, &mut verr);
            digest = fold(digest, vfa as u64);
            digest = fold(digest, verr as u64);

            let mut ext_len = 0usize;
            let ext = zip::mz_zip_extract_archive_file_to_heap(c_zip.as_ptr(), c_arc1.as_ptr(), &mut ext_len, 0);
            digest = fold(digest, ext_len as u64);
            if !ext.is_null() {
                let b = slice::from_raw_parts(ext as *const u8, ext_len);
                digest = fold(digest, bytes_checksum(b));
                mz::mz_free(ext);
            }

            let mut ext2_len = 0usize;
            let mut err2: zip::mz_zip_error = 0;
            let ext2 = zip::mz_zip_extract_archive_file_to_heap_v2(
                c_zip.as_ptr(),
                c_arc2.as_ptr(),
                ptr::null(),
                &mut ext2_len,
                0,
                &mut err2,
            );
            digest = fold(digest, ext2_len as u64);
            digest = fold(digest, err2 as u64);
            if !ext2.is_null() {
                let b = slice::from_raw_parts(ext2 as *const u8, ext2_len);
                digest = fold(digest, bytes_checksum(b));
                mz::mz_free(ext2);
            }

            let add_in_place = zip::mz_zip_add_mem_to_archive_file_in_place(
                c_zip.as_ptr(),
                CString::new("delta.txt").unwrap().as_ptr(),
                if input.is_empty() { ptr::null() } else { input.as_ptr() as *const c_void },
                input.len(),
                ptr::null(),
                0,
                6,
            );
            digest = fold(digest, add_in_place as u64);

            let mut err3: zip::mz_zip_error = 0;
            let add_in_place2 = zip::mz_zip_add_mem_to_archive_file_in_place_v2(
                c_zip.as_ptr(),
                CString::new("epsilon.txt").unwrap().as_ptr(),
                if input.is_empty() { ptr::null() } else { input.as_ptr() as *const c_void },
                input.len(),
                ptr::null(),
                0,
                6,
                &mut err3,
            );
            digest = fold(digest, add_in_place2 as u64);
            digest = fold(digest, err3 as u64);

            let mut zr = MaybeUninit::<zip::mz_zip_archive>::zeroed();
            let prz = zr.as_mut_ptr();
            zip::mz_zip_zero_struct(prz);
            let rinit = zip::mz_zip_reader_init_file(prz, c_zip.as_ptr(), 0);
            digest = fold(digest, rinit as u64);
            if rinit != 0 {
                let num = zip::mz_zip_reader_get_num_files(prz);
                digest = fold(digest, num as u64);

                let exf = zip::mz_zip_reader_extract_file_to_file(prz, c_arc1.as_ptr(), c_out1.as_ptr(), 0);
                digest = fold(digest, exf as u64);

                let loc = zip::mz_zip_reader_locate_file(prz, c_arc2.as_ptr(), ptr::null(), 0);
                digest = fold(digest, loc as u64);
                if loc >= 0 {
                    let exi = zip::mz_zip_reader_extract_to_file(prz, loc as u32, c_out2.as_ptr(), 0);
                    digest = fold(digest, exi as u64);
                }

                let _ = zip::mz_zip_reader_end(prz);
                let _ = zip::mz_zip_end(prz);
            } else {
                let _ = zip::mz_zip_end(prz);
            }

            let mut zr2 = MaybeUninit::<zip::mz_zip_archive>::zeroed();
            let prz2 = zr2.as_mut_ptr();
            zip::mz_zip_zero_struct(prz2);
            let rinit2 = zip::mz_zip_reader_init_file_v2(prz2, c_zip.as_ptr(), 0, 0, 0);
            digest = fold(digest, rinit2 as u64);
            if rinit2 != 0 {
                let loc = zip::mz_zip_reader_locate_file(prz2, c_arc3.as_ptr(), ptr::null(), 0);
                digest = fold(digest, loc as u64);
                if loc >= 0 {
                    let exi = zip::mz_zip_reader_extract_to_file(prz2, loc as u32, c_out3.as_ptr(), 0);
                    digest = fold(digest, exi as u64);
                }
                last_err = zip::mz_zip_get_last_error(prz2) as u64;
                digest = fold(digest, last_err);
                let _ = zip::mz_zip_reader_end(prz2);
                let _ = zip::mz_zip_end(prz2);
            } else {
                last_err = zip::mz_zip_get_last_error(prz2) as u64;
                digest = fold(digest, last_err);
                let _ = zip::mz_zip_end(prz2);
            }

            if let Ok(b) = fs::read(&zip_path) {
                digest = fold(digest, bytes_checksum(&b));
            }
            if let Ok(b) = fs::read(&out1_path) {
                digest = fold(digest, bytes_checksum(&b));
            }
            if let Ok(b) = fs::read(&out2_path) {
                digest = fold(digest, bytes_checksum(&b));
            }
            if let Ok(b) = fs::read(&out3_path) {
                digest = fold(digest, bytes_checksum(&b));
            }

            let mut st = MaybeUninit::<zip::stat64>::zeroed();
            let src_stat = zip::stat64(c_src.as_ptr(), st.as_mut_ptr());
            digest = fold(digest, src_stat as u64);
            let zip_stat = zip::stat64(c_zip.as_ptr(), st.as_mut_ptr());
            digest = fold(digest, zip_stat as u64);
        }

        let _ = fs::remove_file(&zip_path);
        let _ = fs::remove_file(&src_path);
        let _ = fs::remove_file(&out1_path);
        let _ = fs::remove_file(&out2_path);
        let _ = fs::remove_file(&out3_path);
        let _ = fs::remove_dir_all(&dir);
    }

    format!("op=zip_file_ops err={} digest={:016x}", last_err, digest)
}

pub fn ops() -> Vec<(&'static str, fn(&[u8], u64) -> String)> {
    vec![
        ("mz_stream_roundtrip", mz_stream_roundtrip as fn(&[u8], u64) -> String),
        ("tinfl_decode_blob", tinfl_decode_blob as fn(&[u8], u64) -> String),
        ("tdefl_encode_blob", tdefl_encode_blob as fn(&[u8], u64) -> String),
        ("zip_mem_roundtrip", zip_mem_roundtrip as fn(&[u8], u64) -> String),
        ("zip_reader_blob", zip_reader_blob as fn(&[u8], u64) -> String),
        ("zip_file_ops", zip_file_ops as fn(&[u8], u64) -> String),
    ]
}

pub fn gen_seeds(dir: &str) -> Vec<String> {
    let _ = fs::create_dir_all(dir);
    let mut lines = Vec::new();

    let raw1 = make_text_payload(160);
    let raw2 = make_mixed_payload(150);

    for (op, idx, bytes) in [
        ("mz_stream_roundtrip", 1usize, raw1.as_slice()),
        ("mz_stream_roundtrip", 2usize, raw2.as_slice()),
        ("tdefl_encode_blob", 1usize, raw1.as_slice()),
        ("tdefl_encode_blob", 2usize, raw2.as_slice()),
        ("zip_mem_roundtrip", 1usize, raw1.as_slice()),
        ("zip_mem_roundtrip", 2usize, raw2.as_slice()),
        ("zip_file_ops", 1usize, raw1.as_slice()),
        ("zip_file_ops", 2usize, raw2.as_slice()),
    ] {
        let path = format!("{}/{}.{}.bin", dir, op, idx);
        if write_file(&path, bytes) {
            lines.push(format!("seed {} {}", op, path));
        }
    }

    let comp1 = compress_zlib_blob(&raw1, 6)
        .unwrap_or_else(|| Vec::from(&b"x\x9c\x03\x00\x00\x00\x00\x01"[..]));
    let comp2 = compress_zlib_blob(&raw2, 6)
        .unwrap_or_else(|| Vec::from(&b"x\x9c\x03\x00\x00\x00\x00\x01"[..]));
    for (idx, bytes) in [(1usize, comp1.as_slice()), (2usize, comp2.as_slice())] {
        let path = format!("{}/tinfl_decode_blob.{}.bin", dir, idx);
        if write_file(&path, bytes) {
            lines.push(format!("seed tinfl_decode_blob {}", path));
        }
    }

    let z1_members = [
        (raw1[..raw1.len().min(4096)].as_ref(), b"alpha.txt\0".as_slice(), None),
        (raw2[..raw2.len().min(2048)].as_ref(), b"beta.bin\0".as_slice(), Some(b"beta-comment".as_slice())),
        (raw1[..raw1.len().min(1024)].as_ref(), b"gamma/log.json\0".as_slice(), Some(b"gamma-comment".as_slice())),
    ];
    let z2_members = [
        (raw2[..raw2.len().min(3500)].as_ref(), b"alpha.txt\0".as_slice(), None),
        (raw1[..raw1.len().min(2800)].as_ref(), b"beta.bin\0".as_slice(), Some(b"beta-comment-2".as_slice())),
        (raw2[..raw2.len().min(1500)].as_ref(), b"gamma/log.json\0".as_slice(), Some(b"gamma-comment-2".as_slice())),
    ];

    let zip1 = build_zip_blob(&z1_members).or_else(|| {
        build_zip_blob(&[
            (b"seed alpha\n".as_ref(), b"alpha.txt\0".as_slice(), None),
            (b"\x00\x01\x02seed-beta".as_ref(), b"beta.bin\0".as_slice(), None),
            (b"{\"k\":\"v1\"}\n".as_ref(), b"gamma/log.json\0".as_slice(), None),
        ])
    });
    let zip2 = build_zip_blob(&z2_members).or_else(|| {
        build_zip_blob(&[
            (b"another deterministic alpha payload\n".as_ref(), b"alpha.txt\0".as_slice(), None),
            (b"\x10\x20\x30\x40different-beta".as_ref(), b"beta.bin\0".as_slice(), None),
            (b"{\"k\":\"v2\",\"n\":2}\n".as_ref(), b"gamma/log.json\0".as_slice(), None),
        ])
    });

    if let Some(bytes) = zip1 {
        let path = format!("{}/zip_reader_blob.1.bin", dir);
        if write_file(&path, &bytes) {
            lines.push(format!("seed zip_reader_blob {}", path));
        }
    }
    if let Some(bytes) = zip2 {
        let path = format!("{}/zip_reader_blob.2.bin", dir);
        if write_file(&path, &bytes) {
            lines.push(format!("seed zip_reader_blob {}", path));
        }
    }

    lines
}

pub fn gen_perf(dir: &str) -> Vec<String> {
    let _ = fs::create_dir_all(dir);
    let mut lines = Vec::new();

    let raw = make_perf_payload();

    let p1 = format!("{}/mz_stream_roundtrip.perf.bin", dir);
    if write_file(&p1, &raw) {
        lines.push(format!("perf mz_stream_roundtrip {}", p1));
    }

    let p2 = format!("{}/tdefl_encode_blob.perf.bin", dir);
    if write_file(&p2, &raw) {
        lines.push(format!("perf tdefl_encode_blob {}", p2));
    }

    let p3 = format!("{}/zip_mem_roundtrip.perf.bin", dir);
    if write_file(&p3, &raw) {
        lines.push(format!("perf zip_mem_roundtrip {}", p3));
    }

    let p4 = format!("{}/zip_file_ops.perf.bin", dir);
    if write_file(&p4, &raw) {
        lines.push(format!("perf zip_file_ops {}", p4));
    }

    if let Some(comp) = compress_zlib_blob(&raw, 6) {
        let p5 = format!("{}/tinfl_decode_blob.perf.bin", dir);
        if write_file(&p5, &comp) {
            lines.push(format!("perf tinfl_decode_blob {}", p5));
        }
    }

    let n = raw.len();
    let a_end = n.min(2_000_000);
    let b_start = n / 5;
    let b_len = n.min(1_500_000);
    let b_end = b_start.saturating_add(b_len).min(n);
    let c_start = n / 2;

    let members = [
        (raw[..a_end].as_ref(), b"alpha.txt\0".as_slice(), None),
        (raw[b_start..b_end].as_ref(), b"beta.bin\0".as_slice(), Some(b"perf-beta".as_slice())),
        (raw[c_start..].as_ref(), b"gamma/log.json\0".as_slice(), Some(b"perf-gamma".as_slice())),
    ];
    if let Some(zip_bytes) = build_zip_blob(&members) {
        let p6 = format!("{}/zip_reader_blob.perf.bin", dir);
        if write_file(&p6, &zip_bytes) {
            lines.push(format!("perf zip_reader_blob {}", p6));
        }
    }

    lines
}
